      idea: 'Castling on move five leaves e4 undefended on purpose. The pawn is not really on offer — after ...Nxe4 it comes back within a few moves — and the point of not propping the centre up with d3 is that c3 and d4 then arrive as one advance rather than as a repair job. What White buys with that is the sharper version of the opening; what he pays is that Black now chooses the character of the game. The slow game is 5...Be7, where the bishop stands off the diagonal the c3 and d4 build-up will attack rather than being hit with tempo on c5; the forcing game is 5...Nxe4; the bishop-first treatments run 5...b5 6.Bb3 and then ...Bb7 or ...Bc5, aiming at the centre at once and accepting that the bishop will lose time when d4 comes. Underneath all of them sits one piece. White nurses the light-squared bishop along a4-b3-c2 until it looks at h7, and a surprising share of Black’s ideas — ...b5 and ...Na5, ...Nxe4 and ...Nc5, the pawn roll with ...c5-c4 — are ways of trading it off or shutting it in.',
