      idea: 'Recapturing with the queen breaks a beginner’s rule and buys one concrete thing: the queen defends e4, so the knight is not needed on c3, and a c-pawn that is not blocked can go to c4. That is the whole variation — it is the shortest route in the entire Sicilian to the Maróczy Bind, a pawn on c4 and a pawn on e4 with no black counterplay against either. The usual objections do not amount to much. ...e5 gains a tempo on the queen and does so by fixing a backward pawn on d6 and a hole on d5 while developing nothing, which is a bargain White is happy to accept; ...Nc6 is the real question, and it is answered either by pinning the knight with Bb5 or by dropping the queen back to e3. Those two replies are different openings. Bb5 keeps the light-squared bishop and heads for the old scheme of Bxc6, Nc3, Bg5 and long castling. Qe3 is the modern one: it holds e4, stays off the d-file so a rook can use it, and accepts that the bishop on c1 is shut in, because that bishop is going to b2 by way of Rb1 and b3 anyway. The line is rare — a twentieth as popular as 4.Nxd4 — and its practical value is exactly that.',
