      idea: 'Black blocks the check with the piece that offers a trade rather than the one that accepts a tangle, and the trade is worth having on its own terms: exchanges relieve the side with less space, and the bishop being offered is the one that would otherwise spend the game behind ...e6 while White’s sits on an open diagonal. What Black concedes is the thing the whole variation turns on. Once the light-squared bishops come off, White’s c-pawn is free — there is no bishop needing the f1-a6 diagonal and no ...Bg4 to worry about — so c2-c4 and the Maróczy bind arrive a move sooner than in any other Sicilian. The Moscow is therefore not an anti-Sicilian sideline that avoids theory but a way of steering into a bind on favourable terms, and White’s real choice is between two centres: c3 and d4 for a classical big centre, or c4 and d4 for the clamp. Black’s recapture on move four decides which of them is uncomfortable to face.',
