        'Get the king out. Everything wrong with Black’s position traces back to a king that cannot castle quickly, and ...Kf8 is played in some lines precisely because ...g6 and ...O-O are worse.',
        'Free the queenside with ...d5 or ...b6 and ...Bb7 as soon as the tactics allow; until then the a8 rook is not in the game.',
