      idea: 'The rook’s pawn looks like a beginner’s lunge and is in fact the sharpest prophylactic move in the Advance Variation. Black’s entire case for the Caro-Kann over the French is that the light-squared bishop gets outside the pawn chain before ...e6 shuts the door; the bishop has just done so, and 4.h4 makes the natural follow-up unplayable. After 4...e6 5.g4 Be4 6.f3 Bg6 7.h5 the wing pawns simply catch it, and it is the pawn on h4 that makes the chase work, because the square the bishop would retreat to on the b1-h7 diagonal is gone before it gets there. So Black has to answer on the wing too. The principled reply is 4...h5, which stops g4 for good and keeps the bishop, at the permanent cost of the g5 square; the alternative is 4...Qb6, hitting d4, tying the c1 bishop to b2 and preparing ...c5 without touching the kingside. The insertion of h4 and ...h5 is not cosmetic: it makes the quiet fifth moves dangerous. Both 5.c4 and 5.Bd3 are close to harmless in the Advance without those pawns on the board, and with them White has something concrete to work with.',
