      idea: 'Every other Scandinavian begins with ...c6, and this one deliberately does not. The bishop leaves c8 before ...e6 shuts it in, and the tempo saved is meant to buy two things the safety-first order never gets: ...e6 and ...c5 played in one go rather than two, and ...Bb4 pinning the knight that guards d4 at a moment when it actually stings. What Black gives up for it is the escape hatch. Without a pawn on c6 the queen on a5 has nowhere to go when she is asked a question, and White’s tempo-gaining moves therefore all arrive one move earlier than the player expects. The line stands or falls on White’s move order, and the modern verdict is that only one order is testing: the knight before the bishop. 6.Bc4 e6 allows ...Bb4, the trade on c3 and ...Qb6, after which the position dries out into an endgame Black holds, and 6.Bc4 e6 7.Ne5 is met by ...Nbd7 hitting the knight at once. 6.Ne5 first threatens Bc4 against f7 and so forces ...e6 — which is exactly the move that takes c8 and d7 away from the bishop on f5. Only then does g4 come, with the bishop already short of a home.',
